// Normalize booking input into a slot key plus ISO window (per-service duration, KB mirror).
const MINUTES = {'General exam': 30, 'Cleaning and polishing': 45, 'Filling per tooth': 45, 'Root canal': 90, 'Braces consult': 30, 'Implant consult': 30, 'Whitening': 60};
const inp = $input.first().json;
const doctor = inp.doctorName ? String(inp.doctorName).trim() : 'any-doctor';
const date = inp.date ? String(inp.date).trim() : '';
const time = inp.time ? String(inp.time).trim() : '';
const service = inp.serviceName ? String(inp.serviceName).trim() : 'general visit';
const who = inp.patientName ? String(inp.patientName).trim() : 'patient';
const chat = inp.patientChatId ? String(inp.patientChatId) : (inp.patientPhone ? String(inp.patientPhone) : '');
const mins = MINUTES[service] || 30;
const cairoISO = (d, t) => {
  const try2 = d + 'T' + t + ':00+02:00';
  const wall = new Intl.DateTimeFormat('en-GB', { timeZone: 'Africa/Cairo', hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date(try2));
  const hm = wall.split(':');
  const wt = t.split(':');
  return (Number(hm[0]) === Number(wt[0]) && Number(hm[1]) === Number(wt[1])) ? try2 : (d + 'T' + t + ':00+03:00');
};
const start = new Date(cairoISO(date, time));
const end = new Date(start.getTime() + mins * 60 * 1000);
const isPast = isNaN(start.getTime()) || start.getTime() < Date.now() + 15 * 60 * 1000;
return [{ json: { slotKey: 'slot:' + doctor + ':' + date + ':' + time, startISO: isNaN(start.getTime()) ? '' : start.toISOString(), endISO: isNaN(start.getTime()) ? '' : end.toISOString(), doctor: doctor, date: date, time: time, service: service, minutes: mins, patientName: who, patientChat: chat, isPast: isPast } }];

// Decide window state from the events API envelope (always exactly one item).
const inp = $input.first().json;
const prev = $('Build Slot Window').first().json;
const failed = inp.error !== undefined;
const items = failed ? [] : (Array.isArray(inp.items) ? inp.items : []);
const free = !failed && items.length === 0;
const base = { free: free, checkFailed: failed, slotKey: prev.slotKey, startISO: prev.startISO, endISO: prev.endISO, doctor: prev.doctor, date: prev.date, time: prev.time, service: prev.service, patientName: prev.patientName, patientChat: prev.patientChat };
return [{ json: base }];

// Polite slot-taken reply contract for the agent (reads Decide, not passthrough).
let prev = null;
try { prev = $('Decide Slot Free').first().json; } catch (e) { prev = null; }
if (!prev) { prev = $('Build Slot Window').first().json; }
return [{ json: { booked: false, message: 'عذرا، ميعاد ' + prev.date + ' الساعة ' + prev.time + ' مع ' + prev.doctor + ' محجوز. اختر ميعادا آخر من فضلك.', slotKey: prev.slotKey } }];

// Booking-failed contract for the agent (calendar write failed).
const prev = $('Decide Slot Free').first().json;
return [{ json: { booked: false, message: 'تعذر اتمام الحجز لميعاد ' + prev.date + ' الساعة ' + prev.time + '. فريق العمل تم اخطاره.', slotKey: prev.slotKey } }];

// Booking-confirmed contract for the agent (number from queue claim, event from create).
const prev = $('Decide Slot Free').first().json;
const q = $input.first().json;
const eid = $('Create Calendar Event').first().json.id;
const num = q[Object.keys(q)[0]];
return [{ json: { booked: true, eventId: eid ? String(eid) : '', queueNumber: num, message: 'تم الحجز: ' + prev.service + ' مع ' + prev.doctor + ' يوم ' + prev.date + ' الساعة ' + prev.time + ' باسم ' + prev.patientName + '. رقم دورك ' + String(num) + '. العنوان: القاهرة — العنوان التجريبي (DEMO).', slotKey: prev.slotKey } }];

// Verification-failed contract: never claim taken when the check errored.
const prev = $('Decide Slot Free').first().json;
return [{ json: { booked: false, message: 'تعذر التحقق من ميعاد ' + prev.date + ' الساعة ' + prev.time + ' حاليا. فريق العمل تم اخطاره وسيؤكد لك قريبا.', slotKey: prev.slotKey } }];

// Build the reminder record (immutable facts for the reminder engine).
const prev = $('Decide Slot Free').first().json;
const rep = $input.first().json;
const today = new Date().toISOString().slice(0, 10);
return [{ json: { chatId: prev.patientChat, appointmentISO: prev.startISO, bookedDate: today, leadHours: 24, doctor: prev.doctor, service: prev.service, patientName: prev.patientName, slotKey: prev.slotKey, date: prev.date, time: prev.time, eventId: rep.eventId ? rep.eventId : '', queueNumber: rep.queueNumber ? rep.queueNumber : 0 } }];

// 24h cutoff (world dental standard): inside 24h -> staff only.
const inp = $input.first().json;
const trigIn = $('Receive Booking Request').first().json;
const ev = (inp && !inp.error) ? inp : null;
const startMs = ev ? Date.parse(ev.start && (ev.start.dateTime || ev.start.date)) : NaN;
const eid = trigIn.eventId ? String(trigIn.eventId) : '';
if (!eid) { return [{ json: { ok: false, staffOnly: false, message: 'لا أجد رقم الحجز. تواصل مع الاستقبال للإلغاء من فضلك.', eventId: '' } }]; }
if (ev && ev.error !== undefined) { return [{ json: { ok: false, staffOnly: true, message: 'تعذر الوصول للحجز. تم إخطار الطاقم.', eventId: eid } }]; }
if (isNaN(startMs)) { return [{ json: { ok: false, staffOnly: true, message: 'تعذر قراءة الحجز. تم إخطار الطاقم.', eventId: eid } }]; }
const hrsLeft = (startMs - Date.now()) / 3600000;
if (hrsLeft < 24) { return [{ json: { ok: false, staffOnly: true, cutoff: true, message: 'هذا الميعاد خلال أقل من 24 ساعة — الإلغاء عبر الطاقم فقط. تم إخطارهم.', eventId: eid, startISO: new Date(startMs).toISOString() } }]; }
const cairo = new Intl.DateTimeFormat('en-CA', { timeZone: 'Africa/Cairo', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(startMs));
const ctime = new Intl.DateTimeFormat('en-GB', { timeZone: 'Africa/Cairo', hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date(startMs));
return [{ json: { ok: true, eventId: eid, startISO: new Date(startMs).toISOString(),
  date: cairo, time: ctime,
  doctor: trigIn.doctorName ? String(trigIn.doctorName) : 'any-doctor',
  service: trigIn.serviceName ? String(trigIn.serviceName) : 'general visit',
  patientName: trigIn.patientName ? String(trigIn.patientName) : 'patient',
  patientChat: trigIn.patientChatId ? String(trigIn.patientChatId) : '' } }];

// DentAI-style get_patient_appointments: match our summary format, return future bookings.
const inp = $input.first().json;
const trig = $('Receive Booking Request').first().json;
const want = trig.patientName ? String(trig.patientName).trim().toLowerCase() : '';
const items = inp.error !== undefined ? [] : (Array.isArray(inp.items) ? inp.items : []);
const out = [];
for (const ev of items) {
  const sum = ev.summary ? String(ev.summary) : '';
  const desc = ev.description ? String(ev.description) : '';
  if (want && sum.toLowerCase().indexOf(want) === -1 && desc.toLowerCase().indexOf(want) === -1) { continue; }
  const s = ev.start ? (ev.start.dateTime || ev.start.date || '') : '';
  const d = s.slice(0, 10); const t = s.slice(11, 16);
  out.push({ json: { eventId: ev.id, summary: sum, date: d, time: t, startISO: s } });
}
return out.length ? out : [{ json: { none: true, message: 'لا توجد حجوزات قادمة بهذا الاسم.' } }];

// Reschedule = atomic swap. Old inside 24h -> staff only (same dental standard as cancel).
const inp = $input.first().json;
const trig = $('Receive Booking Request').first().json;
const eid = trig.eventId ? String(trig.eventId) : '';
const ev = (inp && inp.error === undefined) ? inp : null;
const startMs = ev ? Date.parse(ev.start && (ev.start.dateTime || ev.start.date)) : NaN;
if (!eid) { return [{ json: { ok: false, message: 'لا أجد رقم الحجز القديم. تواصل مع الاستقبال من فضلك.' } }]; }
if (!ev || isNaN(startMs)) { return [{ json: { ok: false, staffOnly: true, message: 'تعذر قراءة الحجز القديم. تم إخطار الطاقم.', eventId: eid } }]; }
if ((startMs - Date.now()) < 24 * 3600 * 1000) { return [{ json: { ok: false, staffOnly: true, cutoff: true, message: 'هذا الميعاد خلال أقل من 24 ساعة — التأجيل عبر الطاقم فقط. تم إخطارهم.', eventId: eid } }]; }
return [{ json: { ok: true, oldEventId: eid,
  doctor: trig.doctorName ? String(trig.doctorName) : 'any-doctor',
  service: trig.serviceName ? String(trig.serviceName).trim() : 'general visit',
  patientName: trig.patientName ? String(trig.patientName) : 'patient',
  patientChat: trig.patientChatId ? String(trig.patientChatId) : '',
  newDate: trig.newDate ? String(trig.newDate).trim() : '',
  newTime: trig.newTime ? String(trig.newTime).trim() : '' } }];

// New-slot window with Cairo wall time + per-service duration (mirror of book lane).
const MINUTES = {'General exam': 30, 'Cleaning and polishing': 45, 'Filling per tooth': 45, 'Root canal': 90, 'Braces consult': 30, 'Implant consult': 30, 'Whitening': 60};
const c = $('Check Resched Cutoff').first().json;
const mins = MINUTES[c.service] || 30;
const cairoISO = (d, t) => {
  const try2 = d + 'T' + t + ':00+02:00';
  const wall = new Intl.DateTimeFormat('en-GB', { timeZone: 'Africa/Cairo', hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date(try2));
  const hm = wall.split(':'); const wt = t.split(':');
  return (Number(hm[0]) === Number(wt[0]) && Number(hm[1]) === Number(wt[1])) ? try2 : (d + 'T' + t + ':00+03:00');
};
const start = new Date(cairoISO(c.newDate, c.newTime));
const end = new Date(start.getTime() + mins * 60 * 1000);
const bad = isNaN(start.getTime()) || start.getTime() < Date.now() + 15 * 60 * 1000;
return [{ json: { newSlotKey: 'slot:' + c.doctor + ':' + c.newDate + ':' + c.newTime,
  newStartISO: isNaN(start.getTime()) ? '' : start.toISOString(),
  newEndISO: isNaN(start.getTime()) ? '' : end.toISOString(),
  bad: bad, oldEventId: c.oldEventId, doctor: c.doctor, service: c.service,
  patientName: c.patientName, patientChat: c.patientChat,
  newDate: c.newDate, newTime: c.newTime, minutes: mins } }];

// Availability verdict for the NEW slot (always exactly one item).
const inp = $input.first().json;
const prev = $('Build New Slot Window').first().json;
const failed = inp.error !== undefined;
const items = failed ? [] : (Array.isArray(inp.items) ? inp.items : []);
return [{ json: { free: !failed && items.length === 0, checkFailed: failed,
  newSlotKey: prev.newSlotKey, newStartISO: prev.newStartISO, newEndISO: prev.newEndISO,
  oldEventId: prev.oldEventId, doctor: prev.doctor, service: prev.service,
  patientName: prev.patientName, patientChat: prev.patientChat,
  newDate: prev.newDate, newTime: prev.newTime } }];

let prev = null;
try { prev = $('Decide New Free').first().json; } catch (e) { prev = null; }
if (!prev) { prev = $('Build New Slot Window').first().json; }
return [{ json: { moved: false, message: 'عذرا، الميعاد الجديد ' + prev.newDate + ' الساعة ' + prev.newTime + ' محجوز. اختر ميعادا آخر.' } }];

// Re-key the reminder record onto the new slot (confirmation cycle restarts).
let old = null;
try { old = JSON.parse($input.first().json.propertyName || 'null'); } catch (e) { old = null; }
const nw = $('Decide New Free').first().json;
if (!old) { old = { chatId: nw.patientChat, patientName: nw.patientName, doctor: nw.doctor, service: nw.service, queueNumber: 0 }; }
old.appointmentISO = nw.newStartISO; old.date = nw.newDate; old.time = nw.newTime;
old.slotKey = nw.newSlotKey; old.infoSentAt = 0; old.remindedAt = 0; old.confirmedAt = 0;
old.escalatedAt = 0; old.followedUp = 0;
return [{ json: { updated: JSON.stringify(old),
  newKey: 'remind:' + nw.patientChat + ':' + nw.newSlotKey,
  oldEventId: nw.oldEventId, newEventId: '' } }];

// Reschedule contract (Cairo wall time).
const nw = $('Decide New Free').first().json;
const eid = $('Create New Event').first().json.id || '';
const cairo = new Intl.DateTimeFormat('en-CA', { timeZone: 'Africa/Cairo', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(nw.newStartISO));
const ctime = new Intl.DateTimeFormat('en-GB', { timeZone: 'Africa/Cairo', hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date(nw.newStartISO));
return [{ json: { moved: true, newEventId: String(eid), message: 'تم نقل حجزك إلى ' + cairo + ' الساعة ' + ctime + ' (' + nw.service + ' مع ' + nw.doctor + ').' } }];
